/**
 * Invariant 5 — fail build if AUTO-GENERATED sanctuary copies drift from shared source.
 * Run after all sync-*-module.js scripts, before tsc.
 */
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..", "..");
const FUNCTIONS_SRC = path.join(__dirname, "..", "src", "sanctuary");

const AUTO_GENERATED_PREFIX = "// AUTO-GENERATED by ";

function sha256(text) {
  return crypto.createHash("sha256").update(text, "utf8").digest("hex");
}

function stripSyncHeader(content) {
  const lines = content.split("\n");
  if (lines[0]?.startsWith(AUTO_GENERATED_PREFIX)) {
    return lines.slice(1).join("\n");
  }
  return content;
}

function rewriteWonderImports(content) {
  return content.replace(/from "\.\.\/types"/g, 'from "./types"');
}

function rewriteBaitImports(content) {
  return content.replace(/from "\.\.\/types"/g, 'from "./progression/_sanctuaryTypes"');
}

function rewriteFishingImports(content) {
  return content
    .replace(/from "\.\.\/types"/g, 'from "./types"')
    .replace(/from "\.\.\/economy\/callableResponses"/g, 'from "./economy/callableResponses"')
    .replace(/from "\.\.\/random"/g, 'from "./random"')
    .replace(/from "\.\.\/rods\/catalog"/g, 'from "./rodCatalog"')
    .replace(/from "\.\.\/progression\/rodFishingAccess"/g, 'from "./progression/rodFishingAccess"')
    .replace(/from "\.\/castMapping"/g, 'from "./castMapping"')
    .replace(/from "\.\/encounterEngine"/g, 'from "./encounterEngine"');
}

function rewriteEconomyImports(content) {
  return content.replace(/from "\.\.\/wonder\/ledger"/g, 'from "../wonderLedger"');
}

function rewriteProgressionImports(content) {
  return content.replace(/from "\.\.\/types"/g, 'from "./_sanctuaryTypes"');
}

function rewriteRodFishingAccess(content) {
  return content
    .replace(/from "\.\.\/fishing\/encounterEngine"/g, 'from "../encounterEngine"')
    .replace(/from "\.\.\/types"/g, 'from "./_sanctuaryTypes"');
}

/** @type {Array<{ label: string; src: string; dest: string; rewrite?: (c: string) => string; expectHeader?: string }>} */
const MANIFEST = [
  // wonder
  {
    label: "wonder-rules",
    src: path.join(ROOT, "shared", "sanctuary", "wonder", "rules.ts"),
    dest: path.join(FUNCTIONS_SRC, "wonderRules.ts"),
    rewrite: rewriteWonderImports,
    expectHeader: "sync-wonder-module.js",
  },
  {
    label: "wonder-ledger",
    src: path.join(ROOT, "shared", "sanctuary", "wonder", "ledger.ts"),
    dest: path.join(FUNCTIONS_SRC, "wonderLedger.ts"),
    rewrite: rewriteWonderImports,
    expectHeader: "sync-wonder-module.js",
  },
  // bait
  {
    label: "bait-catalog",
    src: path.join(ROOT, "shared", "sanctuary", "bait", "catalog.ts"),
    dest: path.join(FUNCTIONS_SRC, "baitCatalog.ts"),
    rewrite: rewriteBaitImports,
    expectHeader: "sync-bait-module.js",
  },
  // fishing
  ...[
    "encounterEngine.ts",
    "fishingClaimPresentation.ts",
    "fishingOutcomeMessages.ts",
    "castMapping.ts",
    "buildFishingClaimContext.ts",
  ].map((file) => ({
    label: `fishing-${file}`,
    src: path.join(ROOT, "shared", "sanctuary", "fishing", file),
    dest: path.join(FUNCTIONS_SRC, file),
    rewrite: rewriteFishingImports,
    expectHeader: "sync-fishing-module.js",
  })),
  {
    label: "random",
    src: path.join(ROOT, "shared", "sanctuary", "random.ts"),
    dest: path.join(FUNCTIONS_SRC, "random.ts"),
    expectHeader: "sync-fishing-module.js",
  },
  {
    label: "rodFishingAccess",
    src: path.join(ROOT, "shared", "sanctuary", "progression", "rodFishingAccess.ts"),
    dest: path.join(FUNCTIONS_SRC, "progression", "rodFishingAccess.ts"),
    rewrite: rewriteRodFishingAccess,
    expectHeader: "sync-fishing-module.js",
  },
  // progression
  ...[
    "types.ts",
    "moduleRodMap.ts",
    "craftCosts.ts",
    "partsAwards.ts",
    "craftStates.ts",
    "subscriptionCraftGate.ts",
    "fishingPermissions.ts",
    "evaluateCraftable.ts",
  ].map((file) => ({
    label: `progression-${file}`,
    src: path.join(ROOT, "shared", "sanctuary", "progression", file),
    dest: path.join(FUNCTIONS_SRC, "progression", file),
    rewrite: rewriteProgressionImports,
    expectHeader: "sync-progression-module.js",
  })),
  {
    label: "progression-sanctuary-types",
    src: path.join(ROOT, "shared", "sanctuary", "types.ts"),
    dest: path.join(FUNCTIONS_SRC, "progression", "_sanctuaryTypes.ts"),
    expectHeader: "sync-progression-module.js",
  },
  // well
  ...[
    "types.ts",
    "computeAgeBand.ts",
    "catalog-4-6.ts",
    "catalog-6-12.ts",
    "catalog.ts",
    "wellQuestionService.ts",
  ].map((file) => ({
    label: `well-${file}`,
    src: path.join(ROOT, "shared", "sanctuary", "well", file),
    dest: path.join(FUNCTIONS_SRC, "well", file),
    expectHeader: "sync-well-module.js",
  })),
  {
    label: "childProfile-tierAccess",
    src: path.join(ROOT, "shared", "childProfile", "tierAccess.ts"),
    dest: path.join(__dirname, "..", "src", "childProfile", "tierAccess.ts"),
    expectHeader: "sync-child-profile-module.js",
  },
];

// economy synced files (excluding hand-written)
const ECONOMY_SKIP = new Set([
  "economy.test.ts",
  "callableResponses.test.ts",
  "buildEvent.ts",
  "errors.ts",
]);
const ECONOMY_HAND_WRITTEN = new Set(["commitEconomyAction.ts", "resolveCallableIdempotency.ts"]);
const economyDir = path.join(ROOT, "shared", "sanctuary", "economy");
for (const file of fs.readdirSync(economyDir)) {
  if (
    !file.endsWith(".ts") ||
    file.endsWith(".test.ts") ||
    ECONOMY_SKIP.has(file) ||
    ECONOMY_HAND_WRITTEN.has(file)
  )
    continue;
  MANIFEST.push({
    label: `economy-${file}`,
    src: path.join(economyDir, file),
    dest: path.join(FUNCTIONS_SRC, "economy", file),
    rewrite: rewriteEconomyImports,
    expectHeader: "sync-economy-module.js",
  });
}

let failed = false;

for (const entry of MANIFEST) {
  if (!fs.existsSync(entry.src)) {
    console.error(`[sync-integrity] Missing source: ${entry.src}`);
    failed = true;
    continue;
  }
  if (!fs.existsSync(entry.dest)) {
    console.error(`[sync-integrity] Missing dest (run sync scripts): ${entry.dest}`);
    failed = true;
    continue;
  }

  const destRaw = fs.readFileSync(entry.dest, "utf8");
  if (entry.expectHeader && !destRaw.startsWith(`${AUTO_GENERATED_PREFIX}${entry.expectHeader}`)) {
    console.error(
      `[sync-integrity] ${entry.dest} missing AUTO-GENERATED header from sync-${entry.expectHeader}`,
    );
    failed = true;
    continue;
  }

  let expected = fs.readFileSync(entry.src, "utf8");
  if (entry.rewrite) {
    expected = entry.rewrite(expected);
  }

  const actualBody = stripSyncHeader(destRaw);
  const expectedHash = sha256(expected);
  const actualHash = sha256(actualBody);

  if (expectedHash !== actualHash) {
    console.error(
      `[sync-integrity] Drift detected for ${entry.label}:\n  dest: ${entry.dest}\n  Fix: edit shared source and run npm run build (sync scripts).`,
    );
    failed = true;
  }
}

if (failed) {
  process.exit(1);
}

console.log(`[sync-integrity] Verified ${MANIFEST.length} synced sanctuary files.`);
